# cov.ps1 -- Verilator code-coverage suite for the hh-uart RTL.
#
# Builds coverage-instrumented (VL_COVERAGE=ON) Verilator twins of the sim/
# self-checking benches into build/cov/, runs them from sim/, merges them and
# renders an --annotate tree and an lcov .info under build/cov/report/
# (git-ignored). The driver is retrosim-build/tools/vl_cov.ps1; the committed
# baseline is doc/coverage.md, regenerated by tools/cov_summary.py.
#
# These are the SAME SV benches `ninja bench` runs under iverilog, re-elaborated
# by Verilator with --main. Coverage is scoped to the synthesizable RTL
# (rtl/*.sv) by coverage.vlt. Opt-in, not a gate.
#
# Usage:
#   vl\cov.ps1            # configure + build the twins + run + merge + report
#   vl\cov.ps1 -NoBuild   # reuse the existing build/cov twins, just re-run + report
param(
    [switch]$NoBuild      # skip the (re)configure + build of the coverage twins
)
& (Join-Path $PSScriptRoot '..\..\..\retrosim-build\tools\vl_cov.ps1') -VlRoot $PSScriptRoot -NoBuild:$NoBuild
exit $LASTEXITCODE
